class CRMLead {
  update_total() {
    let total = 0
    let total_qty = 0
    let net_total = 0
    let discount_applied = false

    this.doc.products.forEach((d) => {
      total += d.amount
      net_total += d.net_amount
      if (d.discount_percentage > 0) {
        discount_applied = true
      }
    })

    this.doc.total = total
    this.doc.net_total = net_total || total

    if (!net_total && discount_applied) {
      this.doc.net_total = net_total
    }
  }
}

class CRMProducts {
  products_add() {
    let row = this.doc.getRow('products')
    row.trigger('qty')
    this.doc.trigger('update_total')
  }

  products_remove() {
    this.doc.trigger('update_total')
  }

  async product_code(idx) {
    let row = this.doc.getRow('products', idx)

    let a = await call("frappe.client.get_value", {
        doctype: "CRM Product",
        filters: { name: row.product_code },
        fieldname: ["product_name", "standard_rate"],
    })

    row.product_name = a.product_name
    if (a.standard_rate && !row.rate) {
        row.rate = a.standard_rate
        row.trigger("rate")
    }
  }

  qty(idx) {
    let row = this.doc.getRow('products', idx)
    row.amount = row.qty * row.rate
    row.trigger('discount_percentage', idx)
  }

  rate() {
    let row = this.doc.getRow('products')
    row.amount = row.qty * row.rate
    row.trigger('discount_percentage')
  }

  discount_percentage(idx) {
    let row = this.doc.getRow('products', idx)
    if (!row.discount_percentage) {
      row.net_amount = row.amount
      row.discount_amount = 0
    }
    if (row.discount_percentage && row.amount) {
      row.discount_amount = (row.discount_percentage / 100) * row.amount
      row.net_amount = row.amount - row.discount_amount
    }
    this.doc.trigger('update_total')
  }
}

function getCurrentUser() {
  // Prefer frappe.session.user (set by Frappe website base template).
  // Fall back to the user_id cookie (matches frontend/src/stores/session.js).
  const sessionUser = window.frappe?.session?.user
  if (sessionUser && sessionUser !== 'Guest') return sessionUser
  const cookies = new URLSearchParams(document.cookie.split('; ').join('&'))
  const u = cookies.get('user_id')
  return u === 'Guest' ? null : u
}

function getUserRoles() {
  // crm/www/crm.py get_boot() sets window.user_roles on every page load —
  // the most reliable source in the CRM Vue SPA (frappe.boot.user.roles is
  // not populated on website pages, only on desk pages).
  const roles = window.user_roles || window.frappe?.boot?.user?.roles
  return new Set(Array.isArray(roles) ? roles : [])
}

class CRMQuoteRequest {
  onRender() {
    const currentUser = getCurrentUser()
    const userRoles = getUserRoles()
    const isLeadOwner = this.doc.lead_owner === currentUser
    // Privileged-user bypass. Lets Admin / System Manager / Sales Head
    // review / accept / request-revision even when the lead has no Lead Owner
    // assigned yet (common during testing or when a lead is mid-handoff).
    // Sales Manager was retired in the role-hierarchy rewrite; Sales Head
    // is the labelled top-of-org role that matches the operational intent.
    // reviewer_roles is injected into window by crm/www/crm.py (get_boot)
    // from role_config.REVIEWER_ROLES (TIER1_FULL_RW | DOWNSTREAM_SCOPE_ROLES).
    // Empty fallback: if boot data is absent, fail safe (deny review access)
    // rather than granting it via a potentially stale hardcoded list.
    const reviewerRoleSet = new Set(window.reviewer_roles || [])
    const isPrivileged =
      currentUser === 'Administrator' ||
      userRoles.has('Administrator') ||
      [...reviewerRoleSet].some((r) => userRoles.has(r))
    const canReview = isLeadOwner || isPrivileged

    // Lock quote_file for everyone except Estimation Team (the uploaders).
    // Reviewers see it read-only; non-reviewers should not overwrite it either.
    if (!userRoles.has('Estimation Team')) {
      this.setFieldProperty('quote_file', 'read_only', true)
    }

    if (canReview) {
      // Lead Owner / privileged workflow: status dropdown visible so they can
      // Accept or Request Revision. Server-side scripts handle the rest.
      return
    }

    // Estimation Team and everyone else: status is auto-managed by the Before
    // Validate server script (Pending -> Quote Received on file attach).
    // Hiding the dropdown prevents accidental manual changes.
    this.setFieldProperty('status', 'hidden', true)
  }
}

class CRMLead {
  onLoad() {
    // Seed the filter from whatever Source the lead already has when
    // the form opens (covers existing leads, not just new ones).
    this.setFieldProperty(
      'custom_sub_source',
      'link_filters',
      JSON.stringify({ source: this.doc.source || '' })
    )
  }

  source() {
    // Fires whenever the Source field changes. this.value is the new
    // value; setFieldProperty mutates the reactive fieldPropertyOverrides
    // map, which Field.vue's computed reads — Link.vue then reloads its
    // search_link dropdown with the new filter.
    this.setFieldProperty(
      'custom_sub_source',
      'link_filters',
      JSON.stringify({ source: this.value || '' })
    )
  }
}

class CRMLead {
  onLoad() {
    this._applyQuoteFieldLock()
  }

  status() {
    // Re-apply on stage transitions so the lock flips on / off as the
    // Lead enters or leaves C4.
    this._applyQuoteFieldLock()
  }

  _applyQuoteFieldLock() {
    // Outside C4: leave fields editable (server validate is the only gate).
    if (this.doc.status !== 'C4') return
    const roles = new Set(window.frappe?.boot?.user?.roles || [])
    const privileged =
      roles.has('Administrator') ||
      roles.has('System Manager') ||
      roles.has('Sales Head')
    // At C4, lock for everyone EXCEPT privileged users. Mirrors the server
    // bypass in CRMLead._freeze_quote_fields_at_won so privileged users
    // (Admin / SysMgr / Sales Head) can edit the Won quote fields in the
    // UI; everyone else sees disabled inputs and never gets to save-time
    // throw.
    const FIELDS = [
      'custom_final_price',
      'custom_tentative_value',
      'custom_final_margin',
      'custom_final_quote',
      'custom_tentative_area_sqft',
    ]
    for (const f of FIELDS) {
      this.setFieldProperty(f, 'read_only', !privileged)
    }
  }
}

class CRMLead {
  status() {
    // Fires when the user picks a new status. If they're moving the lead
    // to C4 (Won), list any handoff fields that are still blank — saves a
    // save-throw-fix-resave cycle since the server validator would reject
    // the save anyway. Server-side check in the
    // "CRM Lead \u2014 Before Save \u2014 Stage Field Requirements" script
    // remains the source of truth; this is purely a UX nudge.
    if (this.value !== 'C4') return
    const required = [
      ['email', 'Email'],
      ['custom_lead_type', 'Lead Type'],
      ['custom_customer_type', 'Customer Type'],
      ['custom_city', 'City'],
      ['custom_state', 'State'],
      ['custom_pincode', 'Pincode'],
    ]
    if (this.doc.custom_lead_type === 'Projects') {
      required.push(
        ['custom_site_address_full', 'Site Address'],
        ['custom_site_pincode', 'Site Pincode'],
      )
    }
    const missing = required
      .filter(([f]) => !this.doc[f])
      .map(([, label]) => label)
    if (missing.length) {
      toast.warning(
        `Fill these before saving as Won: ${missing.join(', ')}`,
        { duration: 6000 }
      )
    }
  }
}
